# =============================================================================
# GhaniFoods - Wire remaining modules to live Supabase (remove all mock data)
# Run from: D:\Rozmarrah-CUST\Saim Ashraf\Nimko\Working\Code\GhaniFoods
# =============================================================================

$ErrorActionPreference = "Stop"
$root = Get-Location
Write-Host "Root: $root" -ForegroundColor Cyan

$frontend = Join-Path $root "apps\frontend"
if (-not (Test-Path $frontend)) {
    Write-Host "ERROR: apps\frontend not found under $root. Run this script from the GhaniFoods repo root." -ForegroundColor Red
    exit 1
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"

function Backup-File($path) {
    if (Test-Path $path) {
        $backup = "$path.bak-$timestamp"
        Copy-Item $path $backup -Force
        Write-Host "  Backed up -> $backup" -ForegroundColor DarkGray
    }
}

function Write-Base64File($relativePath, $base64Content) {
    $fullPath = Join-Path $frontend $relativePath
    $dir = Split-Path $fullPath -Parent
    if (-not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    Backup-File $fullPath
    $bytes = [System.Convert]::FromBase64String($base64Content)
    [System.IO.File]::WriteAllBytes($fullPath, $bytes)
    Write-Host "  Wrote -> $fullPath" -ForegroundColor Green
}

# -----------------------------------------------------------------------
# 1. Replace lib/store.ts with fully Supabase-wired version
#    (removes ALL seed/dummy arrays, wires wrappers, boxes, carton
#    configurations, production batches, packing runs, customers,
#    invoices, ledger, payments, settings to real Supabase reads + RPCs)
# -----------------------------------------------------------------------
Write-Host "`n[1/4] Rewriting lib/store.ts (dynamic, no local mock state)..." -ForegroundColor Yellow
$storeB64 = ""
Write-Base64File "lib\store.ts" $storeB64

# -----------------------------------------------------------------------
# 2. Add StoreHydrator client component
# -----------------------------------------------------------------------
Write-Host "`n[2/4] Adding components/ui/store-hydrator.tsx..." -ForegroundColor Yellow
$hydratorB64 = ""
Write-Base64File "components\ui\store-hydrator.tsx" $hydratorB64

# -----------------------------------------------------------------------
# 3. Wire StoreHydrator into the dashboard layout
# -----------------------------------------------------------------------
Write-Host "`n[3/4] Wiring StoreHydrator into (dashboard)/layout.tsx..." -ForegroundColor Yellow
$layoutPath = Join-Path $frontend "app\(dashboard)\layout.tsx"
if (Test-Path $layoutPath) {
    Backup-File $layoutPath
    $content = Get-Content $layoutPath -Raw

    if ($content -notmatch "StoreHydrator") {
        $content = $content.Replace(
            'import { NavigationLoadingOverlay } from "@/components/ui/navigation-loading-overlay";',
            'import { NavigationLoadingOverlay } from "@/components/ui/navigation-loading-overlay";' + "`r`n" + 'import { StoreHydrator } from "@/components/ui/store-hydrator";'
        )
        $content = $content.Replace(
            '<NavigationLoadingOverlay />',
            '<NavigationLoadingOverlay />' + "`r`n        " + '<StoreHydrator />'
        )
        [System.IO.File]::WriteAllText($layoutPath, $content, [System.Text.Encoding]::UTF8)
        Write-Host "  Patched -> $layoutPath" -ForegroundColor Green
    } else {
        Write-Host "  Already wired, skipping." -ForegroundColor DarkGray
    }
} else {
    Write-Host "  WARNING: layout.tsx not found at $layoutPath - wire StoreHydrator manually." -ForegroundColor Red
}

# -----------------------------------------------------------------------
# 4. Remove all local mock-data (no longer used by anything)
# -----------------------------------------------------------------------
Write-Host "`n[4/4] Removing lib/mock-data (dummy data no longer needed)..." -ForegroundColor Yellow
$mockDataDir = Join-Path $frontend "lib\mock-data"
if (Test-Path $mockDataDir) {
    $mockBackupDir = Join-Path $frontend "lib\mock-data.removed-$timestamp"
    Move-Item $mockDataDir $mockBackupDir -Force
    Write-Host "  Moved -> $mockBackupDir (delete manually once you confirm nothing references it)" -ForegroundColor Green
} else {
    Write-Host "  lib/mock-data not found, skipping." -ForegroundColor DarkGray
}

# -----------------------------------------------------------------------
# Done - sanity check for leftover mock-data imports across the app
# -----------------------------------------------------------------------
Write-Host "`nScanning for any remaining mock-data imports..." -ForegroundColor Yellow
$hits = Select-String -Path (Join-Path $frontend "app\**\*.tsx"), (Join-Path $frontend "components\**\*.tsx") -Pattern "mock-data" -ErrorAction SilentlyContinue
if ($hits) {
    Write-Host "  Found references still pointing at mock-data - fix these manually:" -ForegroundColor Red
    $hits | ForEach-Object { Write-Host "    $($_.Path):$($_.LineNumber)" -ForegroundColor Red }
} else {
    Write-Host "  Clean - no mock-data imports left." -ForegroundColor Green
}

Write-Host "`n=============================================================================" -ForegroundColor Cyan
Write-Host "DONE. Next steps (manual, cannot be scripted from here):" -ForegroundColor Cyan
Write-Host "  1. Confirm supabase/migrations/0002_functions.sql actually defines:" -ForegroundColor White
Write-Host "     fn_produce_wrapper, fn_produce_box, fn_create_production_batch," -ForegroundColor White
Write-Host "     fn_allocate_overhead, fn_create_packing_run, fn_record_payment," -ForegroundColor White
Write-Host "     fn_create_invoice  -- and that they are pushed: supabase db push" -ForegroundColor White
Write-Host "  2. Run: cd apps/frontend; npm run dev  -- and click through every page" -ForegroundColor White
Write-Host "     (Suppliers, Raw Materials, Packaging, Carton Config, Batches," -ForegroundColor White
Write-Host "      Finished Cartons, Customers, Invoices, Payments, Settings)" -ForegroundColor White
Write-Host "  3. Any TypeScript prop-type errors in page.tsx files calling the old" -ForegroundColor White
Write-Host "     sync store actions (e.g. addWrapper(...) without await) need an" -ForegroundColor White
Write-Host "     'await' added now that these are async Supabase calls." -ForegroundColor White
Write-Host "=============================================================================" -ForegroundColor Cyan